function screenChecklist(){
  const a = army(), f = faction(), units = a.units;
  const entry = k => (D.checklist || {})[k] || { x:1 };
  const rules = f.armyRules.map(r => ({ r, src:f.name + ' army rule' })).concat(detachments().filter(d => d.rule).map(d => ({ r:d.rule, src:d.name })));
  // what another rule of the list gives to units by keyword: "Might of Khorne (Blood Tithe) gives it to BLOOD LEGIONS units"
  const given = name => rules.flatMap(x => (entry('r|' + a.faction + '|' + x.r.name).g || []).filter(g => g.name === name && units.some(u => matches(g.to, u)))
    .map(g => '; ' + esc((g.opt ? g.opt + ' (' + x.r.name + ')' : x.r.name) + ' gives it to ' + kwWords(g.to) + ' units'))).join('');
  const from = s => ' <span class="from">· ' + s + '</span>', naTag = t => t ? ' <span class="tg m">' + esc(t) + '</span>' : '';
  const tl = (boxes, text) => '<div class="tl">' + boxes + '<span>' + text + '</span></div>';
  // several uses as one (phase:your|opp|either; your and opp of one phase: either)
  const ckUnion = us => { const m = {}; for(const u of us) for(const [p, t] of Object.entries(ckMap(u))) m[p] = m[p] && m[p] !== t ? 'either' : t; return Object.entries(m).map(([p, t]) => p + ':' + t).join(','); };
  const items = [];   // { id, kind, e: its entry, line, what, once: its once-per-battle lines [boxes, text] }
  // what a triggered rule or ability puts in force from a rule defined elsewhere (CHECKLIST f): "Riled up (War Cry) · Waaagh!", opening
  // that rule, Active now in the phases the trigger's duration covers (When unclear when the duration cannot be read)
  const forced = (fs, src, kind, id) => { for(const x of fs || []) if(rules.some(y => y.r.name === x.r)) items.push({ id:'f:' + id + ':' + x.r, kind, e:x.x ? { x:1 } : { u:x.u },
    what:x.n, line:linkTo('rule', x.r, x.n.charAt(0).toUpperCase() + x.n.slice(1) + ' (' + src + ')') + from(esc(x.r)), once:null }); };
  for(const x of rules){
    const r = x.r, e = ckStored(entry('r|' + a.faction + '|' + r.name), r), na = inertRule(r.name) ? 'no unit in this list it applies to' : '';
    // "You can only select each of these abilities once per battle" (Kindred Sorcery): a box per option, as on the Overview
    const each = /\beach of these [a-z ]+ once per battle/i.test(r.text) && r.table;
    const pb = !na && !each && perBattle(r, true) && !/per battle\b(?! round)[^.)]*\bper unit\b/i.test(r.text || '') ? perBattle(r, true) : null;
    const line = linkTo('rule', r.name, r.name) + from(esc(x.src) + given(r.name)) + naTag(na), trig = ckListed(e, pb);
    // a rule listed only through options with moments of their own (Code Chivalric's Deeds): the rule, once; its options are in its text
    if(!trig && (e.o || []).some(o => o.s && !units.some(u => u.abilities.some(ab => ab.name === o.n)))){ items.push({ id:'r:' + r.name, kind:'rules', e, line, what:r.name, once:null }); continue; }
    // (what a once-per-battle use puts in force is not listed: its box is)
    if(trig){ items.push({ id:'r:' + r.name, kind:'rules', e, line, what:r.name, once:pb ? [[ticks('r:' + r.name, pb.n, '', r.name), line]] : null }); if(!pb) forced(e.f, r.name, 'rules', 'r:' + r.name); }
    for(const o of e.o || []){
      if(!ckOptListed(o, trig)) continue;   // an option of a rule not listed, or one that is a unit activation
      if(units.some(u => u.abilities.some(ab => ab.name === o.n))) continue;   // an ability it gives units (Protean Purpose): listed as theirs
      const row = each && !na && (r.table.find(t => t[0] === o.row) || [])[0];
      const ol = linkTo('rule', r.name, o.n) + from('option of ' + esc(r.name) + given(o.n)) + naTag(na);
      items.push({ id:'o:' + r.name + ':' + o.n, kind:'rules', e:ckOption(o, e), line:ol, what:o.n, once:row ? [[ticks('r:' + r.name + ':' + row, 1, '', row), ol]] : null });
      forced(o.f, o.n, 'rules', 'o:' + r.name + ':' + o.n);
    }
  }
  // abilities: the same ability on several units is one line, as on the Overview
  const groups = new Map();
  for(const u of units) for(const ab of u.abilities){ const k = ab.name + '|' + ab.text + '|' + (naReason(ab) ? 'na' : ''); if(!groups.has(k)) groups.set(k, { ab, units:[] }); groups.get(k).units.push(u); }
  for(const { ab, units:us } of groups.values()){
    const e = ckStored(entry('a|' + ckHash(ab.name + '\n' + ab.text)), ab), na = naReason(ab), pb = !na && perBattle(ab), key = abilityKey(ab), trig = ckListed(e, pb);
    const aid = 'a:' + ab.name + '|' + ckHash(ab.text) + (na ? '|na' : '');   // (a copy the list cannot use: its own boxes, as its own line)
    if(!trig && !(e.o || []).some(o => o.s)) continue;   // on its datasheet
    const line = linkTo('ability', key, ab.name) + from(esc(unitNames(us)) + given(ab.name)) + naTag(na);
    if(!trig){ items.push({ id:aid, kind:'abs', e, line, what:ab.name, once:null }); continue; }   // listed only through its options: itself, once
    // once per battle: the Overview's boxes, the army's or one set per unit (each copy of a ×N unit)
    const once = !pb ? null : pb.army ? [[abilityTicks(ab, us[0]), line + ' <span class="tg once">per army</span>']]
      : us.flatMap(u => Array.from({ length:u.copies || 1 }, (_, i) => [ticks(copyKey(ab, u, i), pb.n, '', ab.name + (u.copies > 1 ? ', Unit ' + (i + 1) : '')),
        linkTo('ability', key, ab.name) + ' · ' + linkTo('unit', u.id, unitLabel(u)) + (u.copies > 1 ? ' <span class="from">· Unit ' + (i + 1) + '</span>' : '')]));
    items.push({ id:aid, kind:'abs', e, line, what:ab.name, once });
    if(!pb){ forced(e.f, ab.name, 'abs', aid);
      // the ability it selects (pickOptions: Wrathful Presence's, Icon of War from Rod of the War Forge): Active now where that ability is
      // used, within the duration its words give (pk), unless it is listed itself or its own trigger is a unit activation (a)
      if(e.pk) for(const P of pickOptions(ab, us[0]).list){ const eP = ckStored(entry('a|' + ckHash(P.name + '\n' + P.text)), P);
        if(eP.a || ckListed(eP, !naReason(P) && perBattle(P))) continue;
        // where it is used: its own use, or, for one made only of options (Icon of War), theirs when every one is read; none read: When unclear
        // (The Blood God’s Favour, x), not the selector's whole duration
        const oU = !eP.u && (eP.o || []).length && eP.o.every(o => o.u) ? eP.o.map(o => o.u) : null, use = eP.u || (oU && ckUnion(oU));
        items.push({ id:'pk:' + aid + ':' + P.name, kind:'abs', e:e.pk.x || !use ? { x:1 } : ckWithin(use, e.pk.u), what:P.name,
          line:linkTo('ability', abilityKey(P), P.name + ' (' + ab.name + ')') + from(esc(unitNames(us))), once:null }); } }
    for(const o of e.o || []) if(ckOptListed(o, true)){ items.push({ id:'ao' + aid.slice(1) + ':' + o.n, kind:'abs', e:ckOption(o, e), what:o.n,
      line:linkTo('ability', key, o.n) + from('option of ' + esc(ab.name) + ' · ' + esc(unitNames(us))) + naTag(na), once:null }); forced(o.f, o.n, 'abs', 'ao' + aid.slice(1) + ':' + o.n); }
  }
  // each to its sections: a moment, or a phase in one player's turn ("command|your")
  const sec = {}, put = (s, g, html) => { const x = sec[s] = sec[s] || {}; (x[g] = x[g] || []).push(html); };
  const turns = t => t === 'either' ? ['your', 'opp'] : [t];
  for(const it of items){
    const e = it.e;
    if((e.x || !(e.t || e.u || e.at || e.none)) && !(it.once && e.via && (e.via.t || e.via.at))){ put('unclear', it.kind, tl(ckTick('unclear|' + it.id, it.what), it.line)); continue; }
    if(e.none){ put('none', it.kind, tl(ckTick('none|' + it.id, it.what), it.line)); continue; }
    const secs = x => (x.at ? [x.at] : []).concat(Object.entries(ckMap(x.t)).flatMap(([p, t]) => turns(t).map(w => p + '|' + w)), x.ae ? [x.ae] : []);
    const trig = secs(e), act = Object.entries(ckMap(e.u)).flatMap(([p, t]) => turns(t).map(w => p + '|' + w)).filter(s => !trig.includes(s));
    // once per battle: where it is used from (its trigger, its rule's, or else where its effect is used)
    if(it.once){ const via = e.via ? secs(e.via) : []; for(const s of trig.length ? trig : via.length ? via : act) for(const [b, l] of it.once) put(s, 'once', tl(b, l)); continue; }
    for(const s of trig) put(s, 'todo', tl(ckTick(s + '|' + it.id, it.what), it.line));
    for(const s of act) put(s, 'active', tl(ckTick(s + '|' + it.id, it.what), it.line));
  }
  const GROUPS = [['todo', 'To do now', 'to do'], ['active', 'Active now', 'active'], ['once', 'Once per battle', 'once per battle'], ['rules', 'Rules', 'rules'], ['abs', 'Abilities', 'abilities']];
  const phaseSecs = PHASES.flatMap(([p]) => [p + '|your', p + '|opp']);
  // the moments in the order of the game: before the phases, after Fight · Their turn (the end of your opponent's turn, then of the round)
  const order = ['Start of the first battle round', 'Start of the battle round'].filter(s => sec[s]).concat(phaseSecs, ['End of your opponent’s turn', 'End of the battle round', 'unclear', 'none'].filter(s => sec[s]));
  const title = s => s === 'unclear' ? 'When unclear' : s === 'none' ? 'No phase' : s.includes('|') ? PHASE_NAME[s.split('|')[0]] + ' · ' + TURN_NAME[s.split('|')[1]] : s;
  // each section a fold, as the Overview's rules: its name, and on the line under it how many lines each part has
  const fold = s => { const g = sec[s] || {}, parts = GROUPS.filter(([k]) => g[k]), k = 'ck|' + a.id + '|' + s;
    return '<details class="ab rr" data-ckfold="' + esc(k) + '"' + (openStrats.has(k) ? ' open' : '') + '><summary><span class="an"><b>' + esc(title(s)) + '</b><span class="rs">' +
      (parts.length ? metaLine(...parts.map(([x, , w]) => g[x].length + ' ' + w)) : 'nothing') + '</span></span>' + chev + '</summary><div class="body">' +
      (parts.length ? parts.map(([x, l]) => '<div class="ckg"><p class="qh">' + l + '</p>' + g[x].join('') + '</div>').join('') : '<p class="note">Nothing in this list.</p>') + '</div></details>'; };
  return '<div class="ckl"><div class="sec-h"><h2>Phase by phase</h2><button class="textbtn" data-ckreset>Reset</button></div><div class="abl">' + order.map(fold).join('') + '</div>' +
    '<p class="note">Listed: what you must remember when the game reaches a moment: a rule or ability whose own words name the start or end of a battle round, turn or phase, a Command phase, or another phase with a choice (To do now there; a rule listed only through such options is listed once, as the rule), and once-per-battle uses (Once per battle, their box only). Active now: what the others put in force, where it is used and for as long as their words say: their options, the ability they select, and a rule they name in bold as a state units are in (Riled up), unless its own trigger is a unit activation. What activating a unit triggers (selected to shoot, fight or move; each time it attacks, is targeted or destroys) is on its datasheet. When unclear: listed, but no phase can be read from its words. No phase: listed, with no phase. Each line opens the full text. Stratagems are on the Stratagems tab. Reset clears the boxes here, not the once-per-battle ones.</p></div>';
}

function ckOption(o, rule){
  if(o.x) return { x:1 };
  if(o.t || o.at) return { t:o.t, at:o.at, u:o.u };
  if(o.u) return { u:o.u, via:{ t:rule.t, at:rule.at } };
  // none of its own and no use read: in force for the duration its rule's own words give from where it is chosen (oc, derive's
  // coverOf on that duration; pk for an ability's section, Canticles of the Omnissiah): Active now there ("until the end of the battle",
  // Might of Khorne; "until the start of your next Command phase", Shroudpsalm); no duration read: When unclear, not guessed from its
  // rule's trigger; via keeps a once-per-battle one (Kindred Sorcery's) where it is chosen
  const via = rule.t || rule.at ? { t:rule.t, at:rule.at } : null, oc = rule.oc || rule.pk;
  if(oc && oc.u) return via ? { u:oc.u, via } : { u:oc.u };
  return via ? { x:1, via } : { x:1 };
}

function pickCover(text, e){
  const t = plain(rulesText(text));
  if(!/\bselect one of the abilities in the .+? section\b|\bselect one [^.,;]+? ability\b/i.test(t)) return null;
  // the first duration in its words (not the first in DURATIONS' order: "this turn" would win over a later-listed "until the start of your next Command phase")
  const d = DURATIONS.map(x => ({ id:x.id, i:t.search(x.re) })).filter(x => x.i >= 0).sort((a, b) => a.i - b.i)[0];
  return coverOf(d && d.id, e);
}
